use reflow_lib::settings::SettingsStore;
fn main(){let root=std::env::temp_dir().join(format!("reflow-audit-settings-{}",std::process::id()));std::fs::create_dir_all(&root).unwrap();let p=root.join("settings.json");std::fs::write(&p,b"{broken: old preferences").unwrap();let s=SettingsStore::new(p.clone());println!("loaded_original={}",s.loaded_from_disk());let r=s.update(s.get());println!("save_succeeded={} original_still_present={} files={}",r.is_ok(),std::fs::read_to_string(&p).unwrap().contains("broken: old preferences"),std::fs::read_dir(&root).unwrap().count());std::fs::remove_dir_all(root).unwrap();}
